mapper.select:
SELECT n.*, p.province_name, c.city_name
FROM node_info n
LEFT JOIN province p ON n.province_code = p.province_code
LEFT JOIN city c ON n.city_code = c.city_code

    AND n.node_name LIKE CONCAT('%', #{nodeName}, '%')
    AND n.node_type = #{nodeType}
    AND n.province_code = #{provinceCode}
    AND n.city_code = #{cityCode}

ORDER BY n.create_time DESC
